package com.fireplatform;

import com.fasterxml.jackson.databind.*;
import com.fireplatform.alarm.*;
import com.fireplatform.bootstrap.Bootstrap;
import com.fireplatform.configuration.*;
import com.fireplatform.identity.*;
import com.fireplatform.product.JsonPointerParser;
import com.fireplatform.shared.*;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.server.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.mock.web.*;
import org.springframework.test.context.*;
import org.springframework.test.web.servlet.*;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;

@SpringBootTest(properties={"app.roles=api","app.alarm-change-read-enabled=true","app.alarm-change-ws-enabled=true","app.alarm-change-ws-allowed-origins=http://channel.test","app.alarm-change-ws-max-connections=4","app.alarm-change-ws-max-per-session=2","app.storage=h2-dev","spring.datasource.url=jdbc:h2:mem:alarm-channel;MODE=PostgreSQL;DATABASE_TO_LOWER=TRUE;DB_CLOSE_DELAY=-1"})
@AutoConfigureMockMvc(print=org.springframework.boot.test.autoconfigure.web.servlet.MockMvcPrint.NONE) @ActiveProfiles("test") @org.springframework.context.annotation.Import(AlarmChangeChannelIntegrationTest.Observation.class)
class AlarmChangeChannelIntegrationTest {
    @DynamicPropertySource static void environment(DynamicPropertyRegistry r){IngestionIntegrationTest.environment(r);}
    @org.springframework.boot.test.context.TestConfiguration static class Observation {
        @org.springframework.context.annotation.Bean @org.springframework.context.annotation.Primary AlarmWorkbenchIntegrationTest.ObservedDataSource observed(@org.springframework.beans.factory.annotation.Qualifier("dataSource")javax.sql.DataSource actual){return new AlarmWorkbenchIntegrationTest.ObservedDataSource(actual);}
    }
    @Autowired AlarmWorkbenchIntegrationTest.ObservedDataSource observed;
    @Autowired MockMvc mvc;@Autowired ObjectMapper json;@Autowired JdbcTemplate jdbc;@Autowired Bootstrap bootstrap;@Autowired JsonPointerParser parser;@Autowired AlarmChangeChannelTickets tickets;@Autowired AlarmChangeChannelHandshake handshake;@Autowired AlarmChangeChannelHandler handler;@Autowired AuthService auth;@Autowired AlarmChangeChannelHead heads;
    IngestionIntegrationTest f;final List<String> issued=new ArrayList<>();
    @BeforeEach void reset()throws Exception{jdbc.update("DELETE FROM alarm_change_outbox");jdbc.update("DELETE FROM alarm_change_heads");f=new IngestionIntegrationTest();f.mvc=mvc;f.json=json;f.jdbc=jdbc;f.bootstrap=bootstrap;f.parser=parser;f.reset();issued.clear();}
    @AfterEach void release(){for(String raw:issued)try{tickets.release(tickets.claim(raw,"http://channel.test","management"));}catch(ApiError ignored){} }
    ResultActions createTicketRequest(String token,String audience,String tenant,String origin,String body)throws Exception{var b=post("/api/"+audience+"/alarm-change-channel").contentType("application/json").content(body);if(token!=null)b.header("Authorization","Bearer "+token);if(tenant!=null)b.header("X-Tenant-Id",tenant);if(origin!=null)b.header("Origin",origin);return mvc.perform(b);}
    JsonNode issue()throws Exception{var body=f.body(createTicketRequest(f.root,"management","tenant-a","http://channel.test","{}").andExpect(status().isOk()));issued.add(body.get("ticket").asText());return body;}
    Map<String,List<Map<String,Object>>> facts(){var result=new LinkedHashMap<String,List<Map<String,Object>>>();for(String table:jdbc.queryForList("SELECT table_name FROM information_schema.tables WHERE table_schema='public' AND table_type='BASE TABLE' ORDER BY table_name",String.class))result.put(table,jdbc.queryForList("SELECT * FROM "+table));return result;}
    MockHttpServletRequest upgrade(String raw){var request=new MockHttpServletRequest("GET","/api/management/alerts");request.setAttribute(RequestContext.REQUEST_ID,UUID.randomUUID().toString());request.setScheme("http");request.setServerName("channel.test");request.setServerPort(80);request.getServletContext().setAttribute("jakarta.websocket.server.ServerContainer",mock(org.apache.tomcat.websocket.server.WsServerContainer.class));request.addHeader("Origin","http://channel.test");request.addHeader("Upgrade","websocket");request.addHeader("Connection","Upgrade");request.addHeader("Sec-WebSocket-Version","13");request.addHeader("Sec-WebSocket-Key","MDEyMzQ1Njc4OWFiY2RlZg==");request.addHeader("Sec-WebSocket-Protocol","alarm-changes.v1, ticket."+raw);return request;}
    boolean gate(MockHttpServletRequest request,MockHttpServletResponse response,Map<String,Object> attrs)throws Exception{return handshake.beforeHandshake(new ServletServerHttpRequest(request),new ServletServerHttpResponse(response),handler,attrs);}
    @Test void bootstrapHasExactlyFiveFieldsBoundSessionAndZeroWholeSchemaWrites()throws Exception{var before=facts();var b=issue();assertThat(b.size()).isEqualTo(5);assertThat(b.get("v").intValue()).isEqualTo(1);assertThat(b.get("scope").size()).isEqualTo(3);assertThat(b.at("/scope/tenant_id").asText()).isEqualTo("tenant-a");assertThat(b.at("/scope/session").asText()).isEqualTo(AlarmChangeCursor.session(AuthService.hash(f.root)));assertThat(b.get("ticket").asText()).matches("[A-Za-z0-9_-]{43}").isNotEqualTo(f.root);assertThat(b.get("connect_timeout_ms").intValue()).isEqualTo(10000);assertThat(b.get("silence_timeout_ms").intValue()).isEqualTo(15000);assertThat(facts()).isEqualTo(before);}
    @Test void bootstrapStrictEmptyObjectQueryAndOriginFailClosed()throws Exception{for(String body:List.of("null","[]","{\"extra\":1}","{\"ticket\":\"x\",\"ticket\":\"y\"}"))createTicketRequest(f.root,"management","tenant-a","http://channel.test",body).andExpect(status().isBadRequest());for(String origin:List.of("null","http://evil.test","http://channel.test/","HTTP://channel.test","http://channel.test:80"))createTicketRequest(f.root,"management","tenant-a",origin,"{}").andExpect(status().isForbidden());createTicketRequest(f.root,"management","tenant-a",null,"{}").andExpect(status().isForbidden());mvc.perform(post("/api/management/alarm-change-channel?x=1").header("Authorization","Bearer "+f.root).header("X-Tenant-Id","tenant-a").header("Origin","http://channel.test").contentType("application/json").content("{}")).andExpect(status().isBadRequest());mvc.perform(post("/api/management/alarm-change-channel").header("Authorization","Bearer "+f.root).header("X-Tenant-Id","tenant-a").header("Origin","http://channel.test","http://channel.test").contentType("application/json").content("{}")).andExpect(status().isForbidden());}
    @Test void perSessionCapDenialOnlyWritesDeniedAndNeverCreatesBusinessRows()throws Exception{issue();issue();var before=facts();createTicketRequest(f.root,"management","tenant-a","http://channel.test","{}").andExpect(status().isTooManyRequests());var after=facts();assertThat(after.get("audit_log")).hasSize(before.get("audit_log").size()+1);before.remove("audit_log");after.remove("audit_log");assertThat(after).isEqualTo(before);}
    @Test void customerTenantAndAudienceAndSourceAndHashNeverReplaceBearer()throws Exception{String customer=f.login("customer-a",IngestionIntegrationTest.INITIAL,"customer");createTicketRequest(customer,"customer",null,"http://channel.test","{}").andExpect(status().isForbidden());f.call(org.springframework.http.HttpMethod.POST,"/api/auth/change-password",customer,null,null,Map.of("current_password",IngestionIntegrationTest.INITIAL,"new_password",IngestionIntegrationTest.PASSWORD)).andExpect(status().isNoContent());customer=f.login("customer-a",IngestionIntegrationTest.PASSWORD,"customer");var own=f.body(createTicketRequest(customer,"customer",null,"http://channel.test","{}").andExpect(status().isOk()));assertThat(own.at("/scope/tenant_id").asText()).isEqualTo("tenant-a");tickets.release(tickets.claim(own.get("ticket").asText(),"http://channel.test","customer"));createTicketRequest(customer,"customer","tenant-a","http://channel.test","{}").andExpect(status().isForbidden());createTicketRequest(customer,"management","tenant-a","http://channel.test","{}").andExpect(status().isForbidden());createTicketRequest(AuthService.hash(f.root),"management","tenant-a","http://channel.test","{}").andExpect(status().isUnauthorized());createTicketRequest(f.token(f.source("tenant-a",true)),"management","tenant-a","http://channel.test","{}").andExpect(status().isUnauthorized());}
    @Test void claimRechecksCurrentPermissionGrantPasswordAndSessionBefore101()throws Exception{for(String mutation:List.of("DELETE FROM user_permissions WHERE user_id='bootstrap-admin' AND permission='alarm:read'","DELETE FROM user_tenant_grants WHERE user_id='bootstrap-admin' AND tenant_id='tenant-a'","UPDATE app_users SET must_change_password=TRUE WHERE id='bootstrap-admin'","UPDATE sessions SET revoked=TRUE")){var b=issue();jdbc.execute(mutation);var response=new MockHttpServletResponse();assertThat(gate(upgrade(b.get("ticket").asText()),response,new HashMap<>())).isFalse();assertThat(response.getStatus()).isIn(401,403);assertThat(response.getContentAsString()).doesNotContain(b.get("ticket").asText(),f.root);reset();}}
    @Test void successfulClaimHoldsSamePermitAndFailedUpgradeReturnsItOnce()throws Exception{var b=issue();var request=upgrade(b.get("ticket").asText());var response=new MockHttpServletResponse();var attrs=new HashMap<String,Object>();assertThat(gate(request,response,attrs)).isTrue();assertThat(tickets.used()).isEqualTo(1);assertThat(attrs).hasSize(1);var repeat=new MockHttpServletResponse();assertThat(gate(upgrade(b.get("ticket").asText()),repeat,new HashMap<>())).isFalse();assertThat(repeat.getStatus()).isEqualTo(401);handshake.afterHandshake(new ServletServerHttpRequest(request),new ServletServerHttpResponse(response),handler,null);assertThat(tickets.used()).isZero();handshake.afterHandshake(new ServletServerHttpRequest(request),new ServletServerHttpResponse(response),handler,new IllegalStateException());assertThat(tickets.used()).isZero();}
    @Test void upgradeRejectsWrongOriginProtocolQueryAndNonNativeWithoutConsumingGoodTicket()throws Exception{var b=issue();String raw=b.get("ticket").asText();for(int variant=0;variant<5;variant++){var request=upgrade(raw);if(variant==0)request.removeHeader("Origin");if(variant==1){request.removeHeader("Sec-WebSocket-Protocol");request.addHeader("Sec-WebSocket-Protocol","ticket."+raw+", ticket."+raw);}if(variant==2)request.setQueryString("ticket="+raw);if(variant==3)request.getServletContext().removeAttribute("jakarta.websocket.server.ServerContainer");if(variant==4){request.removeHeader("Sec-WebSocket-Protocol");request.addHeader("Sec-WebSocket-Protocol","alarm-changes.v1, ticket."+raw+", other");}var response=new MockHttpServletResponse();assertThat(gate(request,response,new HashMap<>())).isFalse();assertThat(response.getStatus()).isIn(400,403,503);assertThat(response.getContentAsString()).doesNotContain(raw);}var attrs=new HashMap<String,Object>();assertThat(gate(upgrade(raw),new MockHttpServletResponse(),attrs)).isTrue();tickets.release((AlarmChangeChannelTickets.Lease)attrs.get(AlarmChangeChannelHandshake.LEASE));}
    @Test void normalGetAndOtherProtectedRoutesStillNeedOriginalBearer()throws Exception{mvc.perform(get("/api/management/alerts")).andExpect(status().isUnauthorized());mvc.perform(get("/api/management/alarm-changes").header("Upgrade","websocket").header("Connection","Upgrade")).andExpect(status().isUnauthorized());mvc.perform(get("/api/management/alerts/").header("Upgrade","websocket").header("Connection","Upgrade")).andExpect(status().isUnauthorized());}
    @Test void headReadUsesOneActualReadOnlyFeedSnapshotAndDoesNotCountOrWrite()throws Exception{
        String stream=UUID.randomUUID().toString();
        jdbc.update("INSERT INTO alarm_change_outbox(id,tenant_id,recorded_at,publication_sequence,device_id) VALUES(?,?,CURRENT_TIMESTAMP,1,'device-a')",UUID.randomUUID().toString(),"tenant-a");
        jdbc.update("INSERT INTO alarm_change_heads(tenant_id,stream_id,last_sequence) VALUES ('tenant-a',?,1)",stream);
        var before=facts();observed.calls.clear();
        assertThat(heads.read("bootstrap-admin","tenant-a").sequence()).isEqualTo(1);
        assertThat(heads.read("bootstrap-admin","tenant-b").stream()).isNull();
        assertThat(observed.calls).isNotEmpty().allMatch(call->call.isolation()==java.sql.Connection.TRANSACTION_REPEATABLE_READ);
        assertThat(facts()).isEqualTo(before);
    }
}
